// Post-build: write a static HTML file per route with its own title, meta, canonical,
// JSON-LD and a text version of the page content, so crawlers and link previews see
// real page content before JavaScript runs. React replaces #root content on load.
// Regenerate scripts/prerender-routes.json after changing page copy (see scripts/README).
import fs from 'node:fs';
import path from 'node:path';
import { buyerPageSchema } from '../data/buyerPageSchema.js';
import adipecPortfolioLinks from '../data/adipecPortfolioLinks.json' with { type: 'json' };

import turnkeyPage from '../data/turnkeyPage.json' with { type: 'json' };
const SITE = 'https://fann.ae';
const dist = path.resolve('dist');
const template = fs.readFileSync(path.join(dist, 'index.html'), 'utf8');
const routes = JSON.parse(fs.readFileSync(path.resolve('scripts/prerender-routes.json'), 'utf8'));
// One dated source dataset serves the rendered calendar and crawler HTML.
const calendar = JSON.parse(fs.readFileSync(path.resolve('data/exhibitionCalendar.json'), 'utf8'));
const calendarToday = new Intl.DateTimeFormat('en-CA', {timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const calendarEvents = calendar.events.filter(event => event.endDate >= calendarToday);
const calendarEscape = value => String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
const calendarDate = value => new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'));
routes['/events-calendar'] = {
  title:'UAE & Saudi Exhibitions Calendar 2026-2027 | Dates & Venues | FANN',
  description:'Selected upcoming trade shows in Dubai, Abu Dhabi, Riyadh and Jeddah, with organiser date sources and an exhibition stand planning checklist.',
  robots:'index, follow',
  jsonld:JSON.stringify({'@context':'https://schema.org','@type':'CollectionPage',name:'UAE & Saudi Arabia exhibitions calendar 2026-2027',url:SITE+'/events-calendar',dateModified:calendar.checkedOn,mainEntity:{'@type':'ItemList',numberOfItems:calendarEvents.length,itemListElement:calendarEvents.map((event,index)=>({'@type':'ListItem',position:index+1,name:event.name,url:event.source}))}}),
  body:`<main><h1>UAE & Saudi Arabia exhibitions calendar</h1><p>Exhibitor planning | Dates checked ${calendarDate(calendar.checkedOn)}</p><p>Planning an exhibition stand in Dubai, Abu Dhabi, Riyadh or Jeddah? Use this selected 2026-2027 trade-show calendar to match your show, venue and opening date to your stand brief.</p><p>Dates and venues below were checked against organiser or venue pages. This is not a complete regional calendar. Dates can change: confirm with the organiser before booking travel, exhibition space or production. FANN is not the organiser of these shows.</p><a href="/exhibition-stand-quote">Share your show brief</a><h2>Upcoming exhibitions and trade shows</h2>${calendarEvents.map(event=>`<article><h3>${calendarEscape(event.name)}</h3><p><time datetime="${event.startDate}">${calendarDate(event.startDate)}</time> - <time datetime="${event.endDate}">${calendarDate(event.endDate)}</time></p><p>${calendarEscape(event.venue)} | ${calendarEscape(event.country)} | ${calendarEscape(event.industry)}</p><a href="${calendarEscape(event.source)}">Official dates and venue for ${calendarEscape(event.name)}</a></article>`).join('')}<section><h2>Turn a show date into a stand brief</h2><ol><li>Confirm the show, exact venue and your allocated stand dimensions and open sides.</li><li>Get the current exhibitor manual and submission deadlines. Show opening dates are not design, approval or move-in deadlines.</li><li>List products, display sizes, power needs, storage, reception and meeting areas. Add your floor plan if available.</li><li>Agree what the quote includes: design, materials, graphics, venue submissions, installation and any dismantling. Do not assume venue services or overhead rigging are included.</li></ol><p>For multi-venue shows, check the hall and venue on your allocation. The GITEX card lists the exhibition days, 8-11 December; its separate summit day is not a stand-installation deadline.</p><a href="/exhibition-stand-quote">Get a scoped stand quote</a><a href="/services/custom-exhibition-stands-dubai">Dubai stand design and build</a><a href="/exhibition-stand-builders-dubai">Exhibition stand builders in Dubai</a><a href="/fit-out-company-dubai">Office and commercial fit-out in Dubai</a><a href="/exhibition-stands-abu-dhabi">Abu Dhabi exhibition stands</a></section></main>`
};
for (const guide of calendar.guides) {
  const E = calendarEscape;
  routes[guide.path] = { title:guide.name+' Exhibition Stand Planning | FANN',description:guide.intro,robots:'index, follow',jsonld:JSON.stringify({'@context':'https://schema.org','@type':'Article',headline:guide.name+' exhibition stand planning',dateModified:calendar.checkedOn,author:{'@type':'Organization',name:'FANN'},mainEntityOfPage:SITE+guide.path}),body:`<main><a href="/events-calendar">Back to exhibitions calendar</a><h1>${E(guide.name)} exhibition stand planning</h1><p>Dates checked ${calendarDate(calendar.checkedOn)} | ${E(guide.date)} | ${E(guide.venue)}</p><p>${E(guide.intro)}</p><a href="/exhibition-stand-quote">Share your show brief</a>${guide.sections.map(section=>`<section><h2>${E(section.heading)}</h2><p>${E(section.text)}</p></section>`).join('')}<h2>What to send for a scoped quote</h2><p>Send the show, hall and stand allocation, dimensions, open sides, floor plan, products and demonstrations, utilities, brand assets, meeting/storage needs and your actual submission and installation deadlines. Agree design, materials, graphics, venue submissions, fabrication, transport, installation and any dismantling as separate scope items.</p><p>FANN is an independent stand design-and-build company, not the show organiser or an appointed official contractor. This guide does not replace your current exhibitor manual. No stand size, price, permit, deadline or utility capacity is inferred from the show dates.</p>${guide.proof.length?'<h2>Documented stand reference</h2>':''}${guide.proof.map(proof=>`<a href="${proof.path}">${E(proof.label)}</a>`).join('')}<h2>Official planning sources</h2>${guide.sources.map(source=>`<a href="${E(source.url)}">${E(source.label)}</a>`).join('')}<a href="/exhibition-stand-quote">Get a scoped stand quote</a><a href="${guide.name==='ADIPEC 2026'?'/exhibition-stands-abu-dhabi':'/services/custom-exhibition-stands-dubai'}">Explore stand design and build</a></main>`};
  routes['/events-calendar'].body = routes['/events-calendar'].body.replace('</main>',`<p><a href="${guide.path}">${E(guide.name)} exhibitor stand planning guide</a></p></main>`);
}
// Static insight articles (real FANN experience only): crawler HTML + Article/FAQ JSON-LD.
const insightArticles = JSON.parse(fs.readFileSync(path.resolve('data/articles.json'), 'utf8'));
if (routes['/insights']) {
  // Hub stays noindex by design (AI-generated cards); the static articles below are the indexable guides.
  routes['/insights'].body = (routes['/insights'].body || '') + '<h2>FANN guides</h2>';
}
for (const article of insightArticles) {
  const E = calendarEscape;
  const faqLd = article.faqs.map(f=>({'@type':'Question',name:f.q,acceptedAnswer:{'@type':'Answer',text:f.a}}));
  routes[article.path] = {
    lang: article.lang || 'en',
    direction: article.direction || 'ltr',
    title: article.title + ' | FANN',
    description: article.description,
    robots: 'index, follow',
    jsonld: JSON.stringify({'@context':'https://schema.org','@graph':[
      {'@type':'Article',headline:article.title,description:article.description,datePublished:article.datePublished,dateModified:article.datePublished,author:{'@type':'Organization',name:'FANN',url:SITE+'/'},publisher:{'@type':'Organization',name:'FANN',url:SITE+'/',logo:{'@type':'ImageObject',url:SITE+'/logo.png'}},mainEntityOfPage:SITE+article.path,image:SITE+article.hero.src},
      {'@type':'FAQPage',mainEntity:faqLd}
    ]}),
    body: `<main><a href="/insights">All FANN guides</a><article><h1>${E(article.title)}</h1><p>FANN guides | Updated ${E(article.datePublished)}</p><img src="${E(article.hero.src)}" alt="${E(article.hero.alt)}"/>${article.sections.map(section=>`<section><h2>${E(section.heading)}</h2>${section.paras.map(para=>`<p>${E(para)}</p>`).join('')}</section>`).join('')}<section><h2>Common questions</h2>${article.faqs.map(f=>`<h3>${E(f.q)}</h3><p>${E(f.a)}</p>`).join('')}</section><nav><h2>Next steps</h2>${article.related.map(r=>`<a href="${E(r.path)}">${E(r.label)}</a>`).join('')}</nav></article></main>`
  };
  if (routes['/insights']) {
    routes['/insights'].body = (routes['/insights'].body || '') + `<p><a href="${article.path}">${E(article.title)}</a></p>`;
  }
}

// Turnkey page: the same scoped copy and buyer answers serve React and crawlers.
{
 const p=turnkeyPage, E=calendarEscape, url=SITE+'/services/turnkey-exhibition-services-uae';
 routes['/services/turnkey-exhibition-services-uae']={title:p.title,description:p.description,robots:'index, follow',image:'/images/stands/7-dubai-properties-cityscape.webp',jsonld:JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':'Service',name:p.heading,description:p.intro,serviceType:'Turnkey exhibition services',provider:{'@type':'Organization',name:'FANN'},areaServed:{'@type':'Country',name:'United Arab Emirates'}},{'@type':'BreadcrumbList',itemListElement:[{name:'Home',path:'/'},{name:'Services',path:'/services'},{name:p.heading,path:'/services/turnkey-exhibition-services-uae'}].map((b,i)=>({'@type':'ListItem',position:i+1,name:b.name,item:SITE+b.path}))},{'@type':'FAQPage',mainEntity:p.faqs.map(f=>({'@type':'Question',name:f.question,acceptedAnswer:{'@type':'Answer',text:f.answer}}))}]}),body:`<main><h1>${E(p.heading)}</h1><p>${E(p.intro)}</p><a href="/exhibition-stand-quote">Request a scoped proposal</a><img src="/images/stands/7-dubai-properties-cityscape.webp" alt="Existing exhibition stand photograph from FANN's portfolio, not a project-management or workshop photograph."/><h2>Agree the responsibilities before the build</h2><p>Use the same scope checklist for every proposal. One coordinated project still needs clear decisions about who designs, supplies, orders, approves and hands over each part.</p>${p.sections.map(s=>`<section><h2>${E(s.heading)}</h2><p>${E(s.text)}</p>${s.items?'<ul>'+s.items.map(i=>'<li>'+E(i)+'</li>').join('')+'</ul>':''}</section>`).join('')}<h2>Send the allocation and current manual</h2><p>Add your products, visitor activities, brand files and actual submission and installation dates. Ask for an itemised proposal with responsibilities and exclusions.</p><a href="/exhibition-stand-quote">Request a scoped proposal</a><h2>Common buyer questions</h2>${p.faqs.map(f=>`<h3>${E(f.question)}</h3><p>${E(f.answer)}</p>`).join('')}<h2>Related stand planning</h2><a href="/services/custom-exhibition-stands-dubai">Custom stand design and build</a><a href="/services/exhibition-stand-fabrication-dubai">Fabrication and production release</a><a href="/services/modular-exhibition-systems-dubai">Discuss a modular approach</a><a href="/insights/exhibition-stand-brief-checklist">Stand brief checklist</a></main>`};
}

// Quote landing copy and real stand proof also reach no-JavaScript visitors.
routes['/exhibition-stand-quote'].body = '<main><h1>3 free stand designs within 48 hours</h1><p>Send your event brief. Get 3 free stand designs within 48 hours. Choose the one you want, then receive a quote for that design.</p><p>Name, phone and work email are required. Show, stand size, open sides and floor plan are optional. Get 3 free stand designs within 48 hours, then a quote for the design you choose.</p><p>In-house design, fabrication and installation across the UAE.</p><p>Scope and price agreed before production. Any requested changes are confirmed before work proceeds.</p><a href="https://wa.me/971505667502">WhatsApp your brief - skip the form</a><a href="tel:+971505667502">Call FANN</a><h2>Selected work</h2><a href="/portfolio/trevos-light-middle-east"><img src="/images/stands/1-trevos-light-middle-east.webp" alt="TREVOS stand at Light Middle East 2023">TREVOS - Light Middle East 2023</a><a href="/portfolio/bayara-gulfood"><img src="/images/stands/2-bayara-gulfood.webp" alt="Bayara stand at Gulfood 2020">Bayara - Gulfood 2020</a><a href="/portfolio/geven-aircraft-interiors"><img src="/images/stands/6-geven-aircraft-interiors.webp" alt="Geven stand at Aircraft Interiors Middle East 2025">Geven - Aircraft Interiors Middle East 2025</a><h2>Exhibition stand builders: one team, from brief to build</h2><p>3D concept, detailed quote, fabrication and on-site installation. FANN coordinates venue and authority submissions as part of the build.</p><p>Enable JavaScript to send the quote form. You can also email <a href="mailto:sales@fann.ae">sales@fann.ae</a>.</p></main>';
routes['/exhibition-stand-quote'].body += '<section id="buyer-questions"><h2>Exhibition stand buyer Q&amp;A</h2><h3>How much does an exhibition stand cost in Dubai?</h3><p>It depends on stand size, design complexity, materials and what is included, such as graphics, AV, furniture and venue services. Share your stand size and show so we can prepare an itemised proposal. Compare itemised proposals across builders, not only headline prices.</p><a href="/exhibition-stand-quote#brief">Send your stand brief</a></section>';
routes['/exhibition-stand-quote'].body += '<section><h3>Custom stand or modular system - how do we choose?</h3><p>Compare both against the same product dimensions, meeting and storage needs, finish expectations, transport and future show allocations. Ask which parts can be reused and what storage or replacement graphics would require before choosing. If a reusable approach fits better, modular exhibition systems can be discussed.</p><a href="/services/modular-exhibition-systems-dubai">Explore modular exhibition systems</a></section>';
routes['/exhibition-stand-quote'].body += '<section><h3>What is included in a FANN stand quotation?</h3><p>The quotation identifies what is included, what is excluded and who supplies each item. Check materials, graphics, logistics, venue submissions and changes after design approval line by line. If an item is unresolved, ask for it to be confirmed rather than assuming it is included.</p><a href="/exhibition-stand-quote#brief">Send your stand brief</a></section>';
routes['/exhibition-stand-quote'].body += '<section><h3>How long does it take to build an exhibition stand?</h3><p>It depends on the design, materials and show schedule. We plan the build and installation against your show deadline rather than assuming every venue has the same access or approval process. Build timing is confirmed after drawings and materials are reviewed; the free design offer is a separate step, not a promised build duration.</p><a href="/exhibition-stand-quote#brief">Send your stand brief</a></section>';
routes['/exhibition-stand-quote'].body += "<section id=\"design-and-brief-questions\"><h2>Design and brief questions</h2><article id=\"brand-materials\"><h3>Can you work from our brand guidelines and existing materials?</h3><p>Yes. A custom stand is planned around your stand allocation, brand materials and venue requirements. Share your brand guidelines and the materials you want to use with your brief, so they can be considered in the design.</p></article><article id=\"design-feedback\"><h3>Can you revise a design after we review it?</h3><p>Yes. Designs are developed with your feedback before quotation. Tell us what you want to change when you review a design. Any change to the agreed scope, price or schedule needs to be confirmed before work proceeds.</p></article><article id=\"venue-submissions\"><h3>Do you handle venue approvals and submissions?</h3><p>FANN coordinates venue submissions as part of the agreed stand-build scope. The proposal identifies submission responsibility and the drawing-approval sequence. Requirements depend on the venue and project; coordinating a submission is not a guarantee of approval.</p></article><article id=\"start-brief\"><h3>How do we start an exhibition stand project?</h3><p>Send your show and stand size to sales@fann.ae or call +971 50 566 7502. The form on this page requires your name, phone and work email; show, stand size, open sides and floor plan are optional. Share the details you have, and FANN will contact you about your brief and the 3 free stand designs within 48 hours.</p></article><a href=\"/exhibition-stand-quote#brief\">Send your stand brief</a></section>";
// The Dubai stand buyer answer is present in the crawler view as well as React.
const standBuyerAnswer = '<section><h2>Exhibition stands in Dubai: design, build and installation</h2><p>FANN is an exhibition stand contractor in Dubai, with a Dubai office and an in-house workshop in Umm Al Quwain. We design, fabricate and install stands around your show, floor plan and opening date. The quote sets out the agreed materials, graphics, venue submissions, installation and any dismantling, rather than assuming every project includes the same scope.</p><p>See documented Dubai stands: <a href="/portfolio/trevos-light-middle-east">TREVOS at Light Middle East (2023)</a>, <a href="/portfolio/bayara-gulfood">Bayara at Gulfood (2020)</a> and <a href="/portfolio/geven-aircraft-interiors">Geven at Aircraft Interiors Middle East (2025)</a>.</p><p>For a stand proposal, send the show and venue, stand dimensions, number of open sides, floor plan, deadline and what the stand needs to do. <a href="/exhibition-stand-quote">Share your stand brief and optional floor plan</a>.</p></section>';
routes['/'].body += '<p>Exhibiting technology? Use our <a href="/gitex-exhibition-stand-design-dubai">GITEX exhibition stand design brief</a> to plan demos, power and data responsibilities, meetings and the 2026 venue allocation.</p>';
routes['/services/custom-exhibition-stands-dubai'].body = routes['/services/custom-exhibition-stands-dubai'].body.replace('<h2>Built around the show brief</h2>', standBuyerAnswer + '<h2>Built around the show brief</h2>');
